class Solution {
    struct Node {
        int len;
        char pre_c, suf_c;
        int pre_len, suf_len, max_len;
    };

    vector<Node> tree;

    Node merge(const Node& l, const Node& r) {
        Node res;
        res.len = l.len + r.len;
        res.pre_c = l.pre_c;
        res.pre_len = l.pre_len + (l.pre_len == l.len && l.pre_c == r.pre_c ? r.pre_len : 0);
        res.suf_c = r.suf_c;
        res.suf_len = r.suf_len + (r.suf_len == r.len && r.suf_c == l.suf_c ? l.suf_len : 0);
        res.max_len = max(l.max_len, r.max_len);
        if (l.suf_c == r.pre_c) {
            res.max_len = max(res.max_len, l.suf_len + r.pre_len);
        }
        return res;
    }

    void build(int node, int l, int r, const string& s) {
        if (l == r) {
            tree[node] = {1, s[l], s[l], 1, 1, 1};
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, s);
        build(2 * node + 1, mid + 1, r, s);
        tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
    }

    void update(int node, int l, int r, int idx, char ch) {
        if (l == r) {
            tree[node] = {1, ch, ch, 1, 1, 1};
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, ch);
        else update(2 * node + 1, mid + 1, r, idx, ch);
        tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
    }

