class Solution {
    static class Node {
        int len;
        char pre_c, suf_c;
        int pre_len, suf_len, max_len;
    }

    private Node[] tree;

    private Node merge(Node l, Node r) {
        Node res = new Node();
        res.len = l.len + r.len;
        res.pre_c = l.pre_c;
        res.pre_len = l.pre_len + (l.pre_len == l.len && l.pre_c == r.pre_c ? r.pre_len : 0);
        res.suf_c = r.suf_c;
        res.suf_len = r.suf_len + (r.suf_len == r.len && r.suf_c == l.suf_c ? l.suf_len : 0);
        res.max_len = Math.max(l.max_len, r.max_len);
        if (l.suf_c == r.pre_c) {
            res.max_len = Math.max(res.max_len, l.suf_len + r.pre_len);
        }
        return res;
    }

    private void build(int node, int l, int r, String s) {
        if (l == r) {
            tree[node] = new Node();
            char c = s.charAt(l);
            tree[node].len = 1;
            tree[node].pre_c = c;
            tree[node].suf_c = c;
            tree[node].pre_len = 1;
            tree[node].suf_len = 1;
            tree[node].max_len = 1;
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, s);
        build(2 * node + 1, mid + 1, r, s);
        tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
    }

    private void update(int node, int l, int r, int idx, char ch) {
        if (l == r) {
            tree[node].pre_c = ch;
            tree[node].suf_c = ch;
            return;
        }
        int mid = (l + r) / 2;
        if (idx <= mid) update(2 * node, l, mid, idx, ch);
        else update(2 * node + 1, mid + 1, r, idx, ch);
        tree[node] = merge(tree[2 * node], tree[2 * node + 1]);
    }

    public int[] longestRepeating(String s, String queryCharacters, int[] queryIndices) {
        int n = s.length();
        tree = new Node[4 * n];
        build(1, 0, n - 1, s);
        int[] ans = new int[queryCharacters.length()];
        for (int i = 0; i < queryCharacters.length(); i++) {
            update(1, 0, n - 1, queryIndices[i], queryCharacters.charAt(i));
            ans[i] = tree[1].max_len;
        }
        return ans;
    }
}

/**
 * @param {string} s
 * @param {string} queryCharacters
 * @param {number[]} queryIndices
 * @return {number[]}
 */
var longestRepeating = function(s, queryCharacters, queryIndices) {
    const n = s.length;
    const tree = new Array(4 * n);

    function merge(l, r) {
        const len = l.len + r.len;
        const pre_c = l.pre_c;
        const pre_len = l.pre_len + (l.pre_len === l.len && l.pre_c === r.pre_c ? r.pre_len : 0);
        const suf_c = r.suf_c;
        const suf_len = r.suf_len + (r.suf_len === r.len && r.suf_c === l.suf_c ? l.suf_len : 0);
        let max_len = Math.max(l.max_len, r.max_len);
        if (l.suf_c === r.pre_c) {
            max_len = Math.max(max_len, l.suf_len + r.pre_len);
        }
        return { len, pre_c, pre_len, suf_c, suf_len, max_len };
    }

    function build(node, l, r) {
        if (l === r) {
            const ch = s[l];
            tree[node] = { len: 1, pre_c: ch, suf_c: ch, pre_len: 1, suf_len: 1, max_len: 1 };
            return;
        }
        const mid = (l + r) >> 1;
        build(node * 2, l, mid);
        build(node * 2 + 1, mid + 1, r);
        tree[node] = merge(tree[node * 2], tree[node * 2 + 1]);
    }

    function update(node, l, r, idx, ch) {
        if (l === r) {
            tree[node] = { len: 1, pre_c: ch, suf_c: ch, pre_len: 1, suf_len: 1, max_len: 1 };
            return;
        }
        const mid = (l + r) >> 1;
        if (idx <= mid) update(node * 2, l, mid, idx, ch);
        else update(node * 2 + 1, mid + 1, r, idx, ch);
        tree[node] = merge(tree[node * 2], tree[node * 2 + 1]);
    }

    build(1, 0, n - 1);
    const ans = [];
    for (let i = 0; i < queryCharacters.length; i++) {
        update(1, 0, n - 1, queryIndices[i], queryCharacters[i]);
        ans.push(tree[1].max_len);
    }
    return ans;
};
